description:
Objective:
`DoltRepo`: the only file shelling to the `dolt` CLI. Init an isolated campaign
Dolt repo, load a snapshot into a generic `campaign_snapshot` table, commit, and
list commits. Dolt-gated tests.

Files:
- Create: `packages/core/src/persistence/checkpoint/doltRepo.ts`
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/checkpoint.doltRepo.test.ts`

Steps:

1. Write the failing test `packages/core/test/checkpoint.doltRepo.test.ts`:
```ts
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import { DoltRepo } from '../src/persistence/checkpoint/doltRepo.js';
import type { SnapshotRecord } from '../src/persistence/checkpoint/serialize.js';

const doltOk = DoltRepo.available();
const dirs: string[] = [];
function tmp(): string {
  const d = mkdtempSync(join(tmpdir(), 'lw-dolt-'));
  dirs.push(d);
  return d;
}
afterAll(() => {
  /* temp dirs are OS-cleaned; explicit rm omitted for cross-platform safety */
});

const SNAP: SnapshotRecord[] = [
  { table: 'meta', kind: 'schema', ordinal: 0, payload: JSON.stringify({ create: 'CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)' }) },
  { table: 'meta', kind: 'row', ordinal: 0, payload: JSON.stringify({ key: 'a', value: '1' }) },
];

describe.skipIf(!doltOk)('DoltRepo', () => {
  it('init + applySnapshot + commit yields a listable checkpoint', () => {
    const repo = new DoltRepo(join(tmp(), 'dolt'));
    repo.init();
    repo.applySnapshot(SNAP);
    const id = repo.commit('checkpoint: test');
    expect(id).toMatch(/\S+/);
    const log = repo.log();
    expect(log.length).toBeGreaterThanOrEqual(1);
    expect(log[0]?.message).toContain('checkpoint: test');
  });
});

describe('DoltRepo.available', () => {
  it('returns a boolean', () => {
    expect(typeof DoltRepo.available()).toBe('boolean');
  });
});
```

2. Run it to verify FAIL (or the gated suite skipped + the boolean test failing on missing module).
   Command: `npx vitest run packages/core/test/checkpoint.doltRepo.test.ts`
   Expected: FAIL — module not found.

3. Create `packages/core/src/persistence/checkpoint/doltRepo.ts`:
```ts
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync } from 'node:fs';
import type { SnapshotRecord } from './serialize.js';

export interface Checkpoint {
  id: string;
  message: string;
}

function sq(s: string): string {
  return `'${s.replace(/'/g, "''")}'`;
}

export class DoltRepo {
  constructor(private readonly dir: string) {}

  static available(): boolean {
    try {
      execFileSync('dolt', ['version'], { stdio: 'ignore' });
      return true;
    } catch {
      return false;
    }
  }

  private run(args: string[], input?: string): string {
    return execFileSync('dolt', args, {
      cwd: this.dir,
      input,
      encoding: 'utf8',
    });
  }

  init(): void {
    if (!existsSync(this.dir)) mkdirSync(this.dir, { recursive: true });
    if (!existsSync(`${this.dir}/.dolt`)) {
      execFileSync('dolt', ['init'], { cwd: this.dir, stdio: 'ignore' });
    }
    this.run(['config', '--local', '--add', 'user.name', 'loreweaver']);
    this.run(['config', '--local', '--add', 'user.email', 'loreweaver@local']);
  }

  applySnapshot(records: SnapshotRecord[]): void {
    const lines: string[] = [
      'DROP TABLE IF EXISTS campaign_snapshot;',
      'CREATE TABLE campaign_snapshot (' +
        'tbl VARCHAR(255), kind VARCHAR(16), ordinal INT, payload LONGTEXT, ' +
        'PRIMARY KEY (tbl, kind, ordinal));',
    ];
    for (const r of records) {
      lines.push(
        `INSERT INTO campaign_snapshot (tbl, kind, ordinal, payload) VALUES (` +
          `${sq(r.table)}, ${sq(r.kind)}, ${r.ordinal}, ${sq(r.payload)});`,
      );
    }
    this.run(['sql'], lines.join('\n'));
  }

  commit(message: string): string {
    this.run(['add', '-A']);
    this.run(['commit', '--allow-empty', '-m', message]);
    return this.run(['log', '-n', '1', '--oneline']).trim().split(/\s+/)[0] ?? '';
  }

  log(): Checkpoint[] {
    const out = this.run(['log', '--oneline']).trim();
    if (!out) return [];
    return out.split('\n').map((line) => {
      const sp = line.indexOf(' ');
      return sp === -1
        ? { id: line, message: '' }
        : { id: line.slice(0, sp), message: line.slice(sp + 1) };
    });
  }
}
```

4. Add to `packages/core/src/index.ts` (append):
```ts
